SET processing_status = #{processingStatus}, applied = #{applied}, updated_at = CURRENT_TIMESTAMP
WHERE id = #{id}

mapper.delete:
DELETE FROM current_state
WHERE story_id = #{storyId}
  AND category = #{category}
  AND subject = #{subject}
  AND field = #{field}

DELETE FROM current_state
WHERE story_id = #{storyId}
