mapper.select:
SELECT id, story_id, type, subject, description, source_chapter_id, evidence,
       importance, scope, active, created_at, updated_at
FROM story_memory
WHERE story_id = #{storyId}
  AND type = #{type}
  AND subject = #{subject}
  AND active = 1
ORDER BY id ASC
